#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char s[20000][12];

int cmp_str(const void *a, const void *b) {
    return strcmp((const char *)a, (const char *)b);
}

int count_freq(const char *t, int n) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (strcmp(s[mid], t) < 0) lo = mid + 1;
        else hi = mid;
    }
    int first = lo;
    if (first == n || strcmp(s[first], t) != 0) return 0;

    lo = first;
    hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (strcmp(s[mid], t) <= 0) lo = mid + 1;
        else hi = mid;
    }
    return lo - first;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%s", s[i]);
    }

    qsort(s, n, 12, cmp_str);

    long long ans = 0;

    for (int i = 0; i < n; i++) {
        char subs[55][12];
        int sub_count = 0;
        int len = strlen(s[i]);

        for (int start = 0; start < len; start++) {
            for (int end = start; end < len; end++) {
                char temp[12];
                int l = end - start + 1;
                strncpy(temp, s[i] + start, l);
                temp[l] = '\0';

                int found = 0;
                for (int k = 0; k < sub_count; k++) {
                    if (strcmp(subs[k], temp) == 0) {
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    strcpy(subs[sub_count++], temp);
                }
            }
        }

        long long sum = 0;
        for (int k = 0; k < sub_count; k++) {
            sum += count_freq(subs[k], n);
        }

        ans += sum - 1;
    }

    printf("%lld\n", ans);
    return 0;
}
```

